#include "recursant/response_observer.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static long count, fail_at=-1;
static void *alloc(size_t n){if(count++==fail_at)return NULL;return malloc(n);}
static void release(void *p){free(p);}
int main(int argc,char **argv){
 char wire[100000];size_t n=fread(wire,1,sizeof wire,stdin);
 rc_response_observer *o=calloc(1,sizeof *o);assert(o);
 if(argc>1&&!strcmp(argv[1],"alloc")){
   json_set_alloc_funcs(alloc,release);long observed=0;
   for(long f=-1;f<observed;f++){
     memset(o,0,sizeof *o);count=0;fail_at=f;
     rc_response_observer_feed(o,wire,n);json_t *m=rc_response_observer_message(o);
     if(f==-1){assert(m);observed=count;}else assert(!m);
     json_decref(m);
   }
   printf("allocation failure points checked: %ld\n",observed);
 }else{
   size_t step=argc>1?(size_t)atoi(argv[1]):1;if(!step)step=n;
   for(size_t i=0;i<n;i+=step)rc_response_observer_feed(o,wire+i,n-i<step?n-i:step);
   json_t *m=rc_response_observer_message(o);if(m){char *s=json_dumps(m,JSON_COMPACT);puts(s);free(s);json_decref(m);}else puts("PIN");
 }
 free(o);return 0;
}

