void *__real_calloc(size_t,size_t);
void *__wrap_calloc(size_t n,size_t s){
 const char *arm=getenv("SSE_REVIEW_ARM");
 if(n==1&&s==sizeof(rc_response_observer)&&arm&&unlink(arm)==0){fputs("review-observer-calloc-failed\n",stderr);return NULL;}
 return __real_calloc(n,s);
}
